import{_ as a,o as s,c as i,ak as r}from"./chunks/framework.DJ-92fJv.js";const p=JSON.parse('{"title":"🖥️ 解锁控屏限制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/unlock-screen.md","filePath":"features/unlock-screen.md"}'),l={name:"features/unlock-screen.md"};function t(n,e,o,d,c,h){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="🖥️-解锁控屏限制" tabindex="-1">🖥️ 解锁控屏限制 <a class="header-anchor" href="#🖥️-解锁控屏限制" aria-label="Permalink to “🖥️ 解锁控屏限制”">​</a></h1><p><strong>主菜单选项：<code>3</code></strong></p><p>当老师开启<strong>屏幕广播</strong>、<strong>远程控制</strong>或者<strong>屏幕锁定</strong>时，可用此功能摆脱控屏限制。</p><h2 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to “执行流程”">​</a></h2><h3 id="步骤-1-终止屏幕广播进程" tabindex="-1">步骤 1：终止屏幕广播进程 <a class="header-anchor" href="#步骤-1-终止屏幕广播进程" aria-label="Permalink to “步骤 1：终止屏幕广播进程”">​</a></h3><ul><li>终止 <code>ScreenRender.exe</code> — 主屏幕广播进程</li><li>终止 <code>ScreenRender_Y.exe</code> — 屏幕广播辅助进程</li></ul><h3 id="步骤-2-删除控屏锁定程序" tabindex="-1">步骤 2：删除控屏锁定程序 <a class="header-anchor" href="#步骤-2-删除控屏锁定程序" aria-label="Permalink to “步骤 2：删除控屏锁定程序”">​</a></h3><p>脚本自动检测噢易安装路径（优先检测 <code>Program Files (x86)</code>，其次是 <code>Program Files</code>），然后：</p><ul><li>将 <code>ScreenRender.exe</code> <strong>重命名</strong>为 <code>ScreenRender.exe.bak</code><ul><li>这是通过<strong>重命名</strong>而非删除，便于以后恢复</li><li>学生端自动恢复时，也会因找不到该文件而无法启动控屏</li></ul></li></ul><h2 id="关于噢易安装路径" tabindex="-1">关于噢易安装路径 <a class="header-anchor" href="#关于噢易安装路径" aria-label="Permalink to “关于噢易安装路径”">​</a></h2><p>脚本按以下顺序自动检测：</p><ol><li><code>C:\\Program Files (x86)\\Os-Easy\\os-easy multicast teaching system</code></li><li><code>C:\\Program Files\\Os-Easy\\os-easy multicast teaching system</code></li></ol><p>如果未找到安装目录，脚本会跳过此步骤并提示。</p><h2 id="手动执行命令" tabindex="-1">手动执行命令 <a class="header-anchor" href="#手动执行命令" aria-label="Permalink to “手动执行命令”">​</a></h2><p>在 CMD（管理员身份）中依次执行以下命令：</p><h3 id="命令-1-终止屏幕广播主进程" tabindex="-1">命令 1：终止屏幕广播主进程 <a class="header-anchor" href="#命令-1-终止屏幕广播主进程" aria-label="Permalink to “命令 1：终止屏幕广播主进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im ScreenRender.exe</span></span></code></pre></div><p>强制终止主屏幕广播进程，解除远程屏幕控制。</p><h3 id="命令-2-终止屏幕广播辅助进程" tabindex="-1">命令 2：终止屏幕广播辅助进程 <a class="header-anchor" href="#命令-2-终止屏幕广播辅助进程" aria-label="Permalink to “命令 2：终止屏幕广播辅助进程”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im ScreenRender_Y.exe</span></span></code></pre></div><p>强制终止屏幕广播辅助进程，防止广播功能残留。</p><h3 id="命令-3-重命名控屏程序-防止自动恢复" tabindex="-1">命令 3：重命名控屏程序（防止自动恢复） <a class="header-anchor" href="#命令-3-重命名控屏程序-防止自动恢复" aria-label="Permalink to “命令 3：重命名控屏程序（防止自动恢复）”">​</a></h3><div class="language-batch"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C:\\Program Files (x86)\\Os-Easy\\os-easy multicast teaching system\\ScreenRender.exe&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ScreenRender.exe.bak&quot;</span></span></code></pre></div><p>将 <code>ScreenRender.exe</code> 重命名为 <code>.bak</code> 后缀，学生端自动恢复时因找不到该文件而无法启动控屏。如果你的噢易安装在 <code>C:\\Program Files</code> 目录，请相应调整路径。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>✅ 老师正在 <strong>屏幕广播</strong>，你想自己操作电脑</li><li>✅ 老师 <strong>远程控制</strong> 了你的电脑</li><li>✅ 屏幕被 <strong>锁定</strong> 无法操作</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="q-终止后又恢复广播了怎么办" tabindex="-1">Q：终止后又恢复广播了怎么办？ <a class="header-anchor" href="#q-终止后又恢复广播了怎么办" aria-label="Permalink to “Q：终止后又恢复广播了怎么办？”">​</a></h3><p>学生端有自动保护机制，部分版本会重启 <code>ScreenRender.exe</code>。可以进入 <strong>持续监控模式</strong> 自动防御。</p><h3 id="q-找不到-screenrender-exe-文件" tabindex="-1">Q：找不到 ScreenRender.exe 文件？ <a class="header-anchor" href="#q-找不到-screenrender-exe-文件" aria-label="Permalink to “Q：找不到 ScreenRender.exe 文件？”">​</a></h3><p>可能是噢易安装路径不同。手动在 <code>C:\\Program Files</code> 和 <code>C:\\Program Files (x86)</code> 下搜索 <code>Os-Easy</code> 文件夹，找到后手动重命名 <code>ScreenRender.exe</code>。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果老师再次发起屏幕广播，学生端可能会重新生成或启动 <code>ScreenRender.exe</code>。此时可以再次使用此功能或使用 <strong>持续监控模式</strong>（主菜单 → 进程管理 → 选项 11）来自动防御。</p></div>',33)])])}const g=a(l,[["render",t]]);export{p as __pageData,g as default};
